"""Generate presentation assets from unedited run outputs; never rewrite raw_outputs."""
import argparse
import hashlib
from html import escape as esc
import json
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from src.presentation import promo_timeline_svg

REPO='https://github.com/shashank0954/kuku-promo-lab'

def cuts(item):
    return ' + '.join(f"E{s['episode']} {s['start_timestamp']}–{s['end_timestamp']}" for s in item['segments'])

def short(value,limit=125):
    value=' '.join(value.strip('"“”').split())
    return value if len(value)<=limit else value[:limit-1]+'…'

def architecture():
    nodes=[('PARSE','Timed source slices','CODE','#e9f0f8'),('RETRIEVE','Safe promo windows','CODE','#e9f0f8'),('JUDGE','8 finalists by default','OPTIONAL AI','#fff0cd'),('VALIDATE','Every output boundary','CODE','#e0f3eb'),('POST','Approve the exact cut','EDITOR','#e9f0f8')]
    parts=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 148" role="img" aria-label="Hybrid architecture: parse, retrieve, optional judge, validate and editor approval"><style>text{font-family:Arial,sans-serif}</style>']
    for i,(title,sub,tag,color) in enumerate(nodes):
        x=12+i*200
        if i:parts.append(f'<path d="M{x-20} 71h13m-5-5 6 5-6 5" fill="none" stroke="#8a98ac" stroke-width="2"/>')
        parts.extend([f'<rect x="{x}" y="12" width="176" height="119" rx="12" fill="{color}"/>',f'<text x="{x+15}" y="37" font-size="13" font-weight="700" fill="#66768c">{tag}</text>',f'<text x="{x+15}" y="70" font-size="23" font-weight="700" fill="#14223b">{title}</text>',f'<text x="{x+15}" y="100" font-size="14" fill="#41536b">{sub}</text>'])
    return ''.join(parts)+'</svg>'

CSS='''
@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#e8edf3;color:#17263d;font:13px/1.36 Arial,sans-serif}a{color:#275477;text-decoration:none}.page{width:210mm;height:297mm;padding:12mm 14mm;position:relative;background:#fff;margin:18px auto;break-after:page}.page:last-child{break-after:auto}.brand{font-size:10px;font-weight:700;letter-spacing:2px;color:#65738a;border-bottom:2px solid #17263d;padding-bottom:9px;display:flex;justify-content:space-between}.hero{display:flex;justify-content:space-between;gap:20px;margin:18px 0 15px}.hero h1{font-size:37px;letter-spacing:-1.4px;line-height:1.05;margin:0;max-width:490px}.hero .issue{font-size:10px;letter-spacing:1px;text-align:right;color:#728096;min-width:84px}.sub{font-size:14px;color:#5b6a7e;margin:9px 0 0}.tag{display:inline-block;background:#fff1cc;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:700;letter-spacing:.6px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.stat{padding:10px 12px;background:#f2f5f9;border-radius:8px}.stat b{display:block;font-size:27px;line-height:1.1;letter-spacing:-.8px}.stat span{font-size:10px;color:#617086}.section{margin-top:15px}.section h2{font-size:15px;margin:0 0 6px;letter-spacing:-.3px}.section h2 .n{color:#a77c2d;font-size:10px;letter-spacing:1px;margin-right:7px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:13px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.panel{padding:11px 12px;border:1px solid #dce3ed;border-radius:8px}.panel h3{margin:0 0 5px;font-size:12px}.panel p{margin:0;font-size:11.5px;color:#42516a}.body p{margin:5px 0}.muted{color:#607086}.small{font-size:11px}.micro{font-size:10px}.pipeline{width:100%;display:block;margin:2px 0}.rubric{display:flex;border-radius:5px;overflow:hidden;height:26px;margin:8px 0 4px}.rubric span{display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:white}.econ{background:#14233b;color:white;border-radius:8px;padding:12px 14px;margin-top:8px}.econ .big{font-size:24px;font-weight:700;margin-right:10px}.econ p{margin:4px 0;font-size:11.5px;color:#dbe4ef}.footer{position:absolute;bottom:9mm;left:14mm;right:14mm;font-size:9px;color:#718097;border-top:1px solid #dce3ed;padding-top:7px;display:flex;justify-content:space-between}.flow{width:100%}.promo-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.promo{border:1px solid #dce3ed;border-radius:8px;overflow:hidden}.promo .top{background:#f1f5fa;padding:8px 10px;display:flex;justify-content:space-between;font-size:10px;font-weight:700}.promo .inner{padding:9px 10px}.promo h3{font-size:14px;margin:0 0 3px}.timestamp{font-family:monospace;font-size:10.5px;color:#53677f}.evidence{margin:6px 0 0;border-left:3px solid #24a975;padding-left:7px;font-size:11px;line-height:1.3}.evidence.cut{border-color:#dc6176}.label{font-size:8px;letter-spacing:1px;font-weight:700;display:block;color:#687890;margin-bottom:2px}.proof{font-size:11.5px;line-height:1.35}.proof td,.proof th{padding:6px 8px;border-bottom:1px solid #e0e6ef;vertical-align:top;text-align:left}.proof{border-collapse:collapse;width:100%}.proof th{background:#f2f5f9;font-size:10px}.status{color:#11835a;font-weight:bold}.note{background:#f6f8fb;border-left:3px solid #b99856;padding:8px 10px;margin-top:8px;font-size:11px}.timeline{width:100%;display:block}.validation{display:flex;gap:12px;flex-wrap:wrap;font-size:10px;padding:9px 11px;border:1px solid #dce3ed;border-radius:7px;margin-top:9px}.validation b{color:#11835a}ul{padding-left:17px;margin:4px 0}li{margin-bottom:3px}.page+.page .section{margin-top:9px}.page+.page .hero{margin:12px 0 10px}.page+.page .hero h1{font-size:32px}.page+.page .proof td{padding:4px 7px}@media print{body{background:white}.page{margin:0;box-shadow:none}a{color:inherit}}
'''

def promo_card(item,title,label=None):
    label=label or f"POST {item['posting_priority']:02d}"
    return f'''<article class="promo"><div class="top"><span>{label}</span><span>{item['duration']:.1f}s · {item['composite_score']:.1f}/100</span></div><div class="inner"><h3>{esc(title)}</h3><div class="timestamp">{esc(cuts(item))}</div><p class="evidence"><span class="label">OPENING EVIDENCE · ABRIDGED</span>{esc(short(item['hook_text']))}</p><p class="evidence cut"><span class="label">UNRESOLVED CUT</span>{esc(short(item['cliffhanger_text'],95))}</p></div></article>'''

def build(tests):
    source=ROOT/'raw_outputs/all_episodes_promos_ranked.json'
    before=hashlib.sha256(source.read_bytes()).hexdigest()
    data=json.loads(source.read_text());run=data['run'];audit=data['audit']
    assert run['episode_count']==50,'Build the submission visuals from the complete 50-episode run.'
    assert run['provider']['judged_candidates']==0,'This presentation template describes an offline snapshot; regenerate that run or update its disclosure.'
    evaluation=json.loads((ROOT/'evaluation/metrics.json').read_text())
    development=json.loads((ROOT/'raw_outputs/editorial_regression_review.json').read_text())
    ordered=sorted(data['promos'],key=lambda x:x['posting_priority']);first=ordered[0]
    challenger=next(x for x in ordered if x['id']=='E25-13.2-33.8')
    assets=ROOT/'assets';dest=ROOT/'deliverables';assets.mkdir(exist_ok=True);dest.mkdir(exist_ok=True)
    (assets/'architecture.svg').write_text(architecture())
    (assets/'promo_timeline.svg').write_text(promo_timeline_svg(first))
    overview=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1400 530" role="img" aria-label="Kuku Promo Lab: verified offline submission"><style>text{{font-family:Arial,sans-serif}}</style><rect width="1400" height="530" rx="24" fill="#0d182a"/><rect x="48" y="47" width="5" height="32" fill="#e6b85b"/><text x="72" y="72" fill="#e7bd69" font-size="18" font-weight="700" letter-spacing="3">KUKU / PROMO LAB</text><text x="62" y="163" fill="#f4f7fb" font-size="59" font-weight="700" letter-spacing="-2">Find the moment.</text><text x="62" y="228" fill="#f4f7fb" font-size="59" font-weight="700" letter-spacing="-2">Cut before the answer.</text><text x="64" y="280" fill="#aebbd0" font-size="22">Source-grounded promo discovery · Problem 01</text><rect x="959" y="51" width="375" height="53" rx="10" fill="#1b2e47"/><text x="984" y="84" fill="#a9ddc4" font-size="17" font-weight="700">OFFLINE RUN · SWAPPABLE AI JUDGE</text>'''
    for i,(value,label) in enumerate([(str(run['episode_count']),'EPISODES ANALYZED'),(str(len(data['promos'])),'SHORTLISTED PROMOS'),(f"{audit['passed']}/{audit['hard_checks']}",'SOURCE CHECKS PASSED'),(str(tests),'TESTS PASSING')]):
        x=64+i*330
        overview+=f'<rect x="{x}" y="340" width="292" height="117" rx="12" fill="#16263d"/><text x="{x+20}" y="392" fill="#f2f7ff" font-size="38" font-weight="700">{value}</text><text x="{x+20}" y="428" fill="#aab8cd" font-size="13" letter-spacing="1">{label}</text>'
    overview+='<text x="65" y="499" fill="#8799b4" font-size="15">20–60s cuts · first-3s hooks · unresolved endings · script-based estimates; editor review required</text></svg>'
    (assets/'submission_overview.svg').write_text(overview)
    footer=lambda n:f'<footer class="footer"><span>KUKU · AI GENERALIST ASSIGNMENT · PROBLEM 01</span><span>{before[:12]} · {n}/2</span></footer>'
    brands=lambda right:f'<div class="brand"><span>KUKU / PROMO LAB</span><span>{right}</span></div>'
    page1=f'''<section class="page"><div class="flow">{brands('SOLUTION / 01')}<div class="hero"><div><h1>Find the moment.<br>Cut before the answer.</h1><p class="sub">A practical shortlisting tool for cold-audience microdrama ads.</p></div><div class="issue">PROBLEM 01<br><br><span class="tag">20–60s</span></div></div>
    <div class="stats"><div class="stat"><b>{run['episode_count']}</b><span>episodes analyzed</span></div><div class="stat"><b>{len(data['promos'])}</b><span>promos shortlisted</span></div><div class="stat"><b>{audit['passed']}/{audit['hard_checks']}</b><span>structural checks passed</span></div><div class="stat"><b>{tests}</b><span>automated tests passing</span></div></div>
    <div class="section body"><h2><span class="n">01</span> Solve the editor’s decision</h2><p>Editors need usable moments and exact cut points, not another episode summary. I chose Problem 1 because safe edit boundaries are computational, while betrayal, clarity and unresolved tension need editorial judgment.</p><p class="small muted"><b>Assumptions:</b> source timestamps are authoritative; duration is inclusive at 20–60s; dialogue stays whole; mashups use two segments. Some episodes have no suitable cut. No video, campaign data or exhaustive-recall guarantee is assumed.</p></div>
    <div class="section"><h2><span class="n">02</span> Code protects the cut. AI critiques the story.</h2><img class="pipeline" src="assets/architecture.svg" alt="Parse, retrieve, optional AI judge, code validation and editor approval"/><div class="grid3"><div class="panel"><h3>CODE · deterministic rules</h3><p>{run['beat_count']:,} beats become {run['timeline_slice_count']:,} audiovisual slices. Retrieve windows, preserve source boundaries, reject mid-dialogue edits and audit every output.</p></div><div class="panel"><h3>AI · swappable critique</h3><p>Gemini, OpenAI or Anthropic judges up to eight finalists by default. Keys and model IDs are editable. Six findings cite validated source beat IDs. Top + borderline sampling stays within budget; AI cannot move cuts.</p></div><div class="panel"><h3>EDITOR · final approval</h3><p>Compare two cuts, save notes, approve script and footage separately. Input-scoped decisions import/export independently; editor-selected shortlist leaves raw outputs intact.</p></div></div></div>
    <div class="section"><h2><span class="n">03</span> Five signals, one transparent score</h2><div class="rubric"><span style="width:30%;background:#183956">Hook 30%</span><span style="width:30%;background:#36647e">Cliffhanger 30%</span><span style="width:20%;background:#64889a">Clarity 20%</span><span style="width:10%;background:#8598ad">Heat 10%</span><span style="width:10%;background:#acb9c9;color:#20344b">Pace 10%</span></div><p class="micro muted">Heuristic scores remain the sole score ordering. Recommended cuts precede review-required cuts. AI scores stay separate; supported AI concerns can veto. Long-beat timing and mashup continuity are categorical review needs, never confidence percentages.</p></div>
    <div class="section"><h2><span class="n">04</span> Scale the filtering, then spend on finalists</h2><div class="econ"><span class="big">$0</span><b>API fees for the saved offline run</b><p>Recorded scoring/audit time: {run['elapsed_seconds']:.2f}s locally. Eight finalists, in batches of four, bound live inference. Two batches at an assumed 8s add ~16s; live latency is unmeasured.</p></div><p class="small">Worked example: 14,400 input + 1,280 output tokens at historical $0.30/$2.50 per million = <b>$0.00752/show</b>, ~$1.50 for 200 weekly shows. This is an editable scenario, not a current-model quote or invoice; hosting, retries and editor time are separate.</p><p class="small muted">The actual input is ~67.8k estimated tokens. A three-pass premium scenario at $2.50/$10 per million with 10k output tokens costs ~$0.61. Scale through independent show workers, input/model-version caches and rate limits. A sliding 60s boundary index would replace the current boundary-pair enumeration and repeated beat scans.</p></div>
    </div>{footer(1)}</section>'''
    cards=''.join([promo_card(ordered[0],'Script recommendation 1'),promo_card(ordered[1],'Script recommendation 2')])
    followup=f'<p class="small"><b>POST 03 · {esc(cuts(ordered[2]))}</b> · {ordered[2]["duration"]:.1f}s · {esc(short(ordered[2]["hook_text"],75))}<br>Review need: {esc("; ".join(ordered[2].get("decision",{}).get("reasons",[])))}</p>'
    page2=f'''<section class="page"><div class="flow">{brands('EVIDENCE / 02')}<div class="hero"><div><h1>Post the conflict.<br>Cut before the payoff.</h1><p class="sub">An editor’s playbook, with the weak picks left visible.</p></div></div>
    <div class="section"><h2><span class="n">05</span> Actual posting order + one test challenger</h2><div class="promo-grid">{cards}</div>{followup}<p class="micro muted">Source evidence is abridged. Every recommendation needs footage approval. Test reviewed variants with equal spend; compare 3s hold, click-through and downstream starts. No lift has been measured.</p></div>
    <div class="section"><h2><span class="n">06</span> The cut is inspectable</h2><img class="timeline" src="assets/promo_timeline.svg" alt="Exact source timeline for the first recommended promo"/><p class="micro muted">First recommendation: {esc(cuts(first))}. Color marks review windows, not additional edits. Exact source cut points are retained.</p></div>
    <div class="section"><h2><span class="n">07</span> Real failures, concrete corrections</h2><table class="proof"><thead><tr><th>Actual source case</th><th>Bad decision</th><th>Correction</th></tr></thead><tbody><tr><td>E30 · 00:03.00–00:43.50</td><td>Earlier rule mistook a watch “chain” for attack.</td><td class="status">Reject the false hook.</td></tr><tr><td>E49 · 01:24.00–01:52.80</td><td>Earlier rule mistook metaphor for injury.</td><td class="status">Exclude metaphorical heat.</td></tr><tr><td>E21 · 00:47.30–01:39.20</td><td>The child recovers before a Duchess subplot question.</td><td class="status">Reject the resolved arc.</td></tr></tbody></table><p class="micro muted">{development['total']} development regressions; {evaluation['sample_size']} frozen diverse cases await genuine human labels. Precision and pairwise agreement are pending; no recall claim. E22: SFX ends 00:42.80 vs scene 00:42.50; the real timestamp is retained and flagged.</p></div>
    <div class="grid2 section"><div class="panel"><h3>AI tools used · one actual mistake</h3><p>Codex assisted code, rubric design, testing and docs. An early rule matched “hang” inside “cliffhanger,” promoting a calm cello ending in E16 00:59.00–01:23.19. Source inspection, word boundaries and regression tests corrected it.</p></div><div class="panel"><h3>Rerun it in the interview</h3><p>Use the original synthetic sample or upload TXT/ZIP files. Select episodes (e.g. 2, 5, 8–10), choose a model/key, test the API and rerun. HTTP 503 gets bounded retries; exhausted requests remain visibly unsuccessful.</p></div></div>
    <div class="validation"><span><b>{audit['passed']}/{audit['hard_checks']}</b> structurally valid candidates</span><span><b>{tests}</b> tests in a clean pinned setup</span><span>Saved run: <b>offline</b></span></div>
    <p class="micro muted">Limits: long-beat onset, rhetorical questions and mashup causality need review. No footage, ad-lift or successful live inference verified; provider contracts use mocks.</p>
    <p class="micro"><a href="{REPO}">Prototype / code</a> · <a href="{REPO}/tree/main/raw_outputs">Unedited outputs</a> · <a href="https://ai.google.dev/gemini-api/docs/pricing">Google pricing reference</a></p>
    </div>{footer(2)}</section>'''
    (ROOT/'SOLUTION_DOC.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Kuku · Solution</title><style>'+CSS+'</style></head><body>'+page1+page2+'</body></html>')
    (ROOT/'SOLUTION_DOC.md').write_text(f"""# Kuku Promo Lab — Problem 1

Problem: help editors choose defensible 20–60s cold-viewer promos. Script timing is authoritative; dialogue stays whole; current mashups contain two segments. No footage or campaign performance is available.

## Architecture and editorial policy
Code parses {run['episode_count']} episodes / {run['beat_count']} beats and validates exact cuts, duration, dialogue and overlap. These are structural checks, not proof of editorial quality. AI optionally critiques opening, conflict, unresolved ending, answers already supplied, missing context and continuity with validated selected beat IDs. Unsupported references reject the batch; AI never changes cuts. The budget includes deterministic top and borderline candidates.

{run['ranking_policy']}

Uncertainty is categorical: supported by script timing; uncertain within a long source beat; requires continuity review; insufficient evidence. Review needs accompany recommendations. Editors compare candidates, record separate script/footage decisions and export an independent selected shortlist. Script review never grants footage approval.

## Actual output and posting order
{len(ordered)} shortlisted; {audit['passed']}/{audit['hard_checks']} structurally valid emitted candidates. First cuts: {cuts(ordered[0])}; {cuts(ordered[1])}; {cuts(ordered[2])}. Prioritize timing-supported, understandable conflict before review-required bridges. No measured ad lift.

## Quality evidence and failure
{development['matched']}/{development['total']} curated development regressions pass; these are not independent quality labels. A frozen {evaluation['sample_size']}-case diverse sample includes rejected and borderline windows. Human labeling is {evaluation['status']}; acceptance precision and pairwise agreement remain unreported until genuine labels exist. No recall claim. E21 00:47.30–01:39.20 resolves the child rescue before a Duchess question and is rejected. AI-assisted development once misread hang inside cliffhanger; source review and word boundaries corrected that rule.

## Scale and economics
Offline measured API usage: zero calls, zero tokens, $0. Local elapsed {run['elapsed_seconds']:.3f}s. Eight finalists with 14,400 input / 1,280 output tokens at historical $0.30/$2.50 per million estimate $0.00752/show; live structured critiques can use more output. Editable assumptions, not measured live prices or bills. Independent show workers scale under quotas; footage review remains manual. No successful live inference verified. Codex assisted implementation, tests and documentation; provider tests use mocks.
""")
    # Standalone, searchable visual companion. It never overwrites or replaces the full raw exports.
    webcards=[]
    for item in ordered:
        episodes=','.join(str(s['episode']) for s in item['segments'])
        tags=' '.join(f'<span>{esc(k.replace("_score", "").replace("_", " "))}: {v}</span>' for k,v in item['scores'].items())
        webcards.append(f'''<article class="webcard" data-kind="{item['kind']}" data-episodes="{episodes}"><header><b>POST {item['posting_priority']:02d}</b><span>COMPOSITE #{item['rank']} · {item['composite_score']:.1f}/100</span></header><h2>{esc(cuts(item))}</h2><p class="duration">{item['duration']:.2f}s · {esc(item['posting_strategy'])}</p>{promo_timeline_svg(item)}<div class="webquotes"><div><label>OPENING HOOK</label><p>{esc(item['hook_text'])}</p></div><div><label>CLIFFHANGER</label><p>{esc(item['cliffhanger_text'])}</p></div></div><p>{esc(item['why_it_works'])}</p><p class="muted">{esc(item['posting_reason'])}</p><div class="subscores">{tags}</div><details><summary>Review flags &amp; scoring source</summary><p>{esc('; '.join(item['editorial_flags']) or 'No automated flags; footage review still required.')}</p><p>{esc(item['ranking_rationale'])}</p><small>{esc(item['evaluation_source'])}</small></details></article>''')
    opts=''.join(f'<option value="{e["episode"]}">Episode {e["episode"]}</option>' for e in run['episode_coverage'])
    webcss='''*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#17263d;font:15px/1.5 Arial,sans-serif}main{max-width:1150px;margin:auto;padding:36px 24px}h1{font-size:48px;line-height:1.07;letter-spacing:-2px;margin:14px 0}a{color:#285d7f}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:700;color:#8b6c31}.lead{max-width:780px;color:#5d6d82}.actions{display:flex;flex-wrap:wrap;gap:18px;margin:20px 0}.controls{display:flex;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#eef2f7ed;padding:14px 0;z-index:2}input,select{font:inherit;border:1px solid #c8d3e1;border-radius:8px;padding:10px;background:white}input{flex:1;min-width:220px}.webcard{background:white;border:1px solid #d5deea;border-radius:14px;padding:22px;margin:18px 0}.webcard header{display:flex;justify-content:space-between;color:#586f88;font-size:12px}.webcard header b{color:#a77b29}.webcard h2{font-size:21px;margin:12px 0 4px}.duration,.muted{color:#687a8e}.webcard svg{width:100%;max-height:170px;margin:6px 0}.webquotes{display:grid;grid-template-columns:1fr 1fr;gap:20px}.webquotes>div{border-left:3px solid #27ae79;padding:0 12px}.webquotes>div+div{border-color:#df5870}label{font-size:11px;letter-spacing:1px;font-weight:700;color:#61758e}.webquotes p{margin:7px 0}.subscores{display:flex;flex-wrap:wrap;gap:8px}.subscores span{font-size:12px;background:#eef2f8;padding:4px 8px;border-radius:5px}details{margin-top:14px;font-size:13px}summary{cursor:pointer}footer{font-size:12px;color:#738499;margin:26px 0}article[hidden]{display:none}@media(max-width:700px){h1{font-size:36px}.webquotes{grid-template-columns:1fr}.webcard header{display:block}.webcard header span{display:block}}@media print{.controls{position:static}details{display:block}.webcard{break-inside:avoid}}'''
    js='''const cards=[...document.querySelectorAll('.webcard')];function filter(){const q=document.querySelector('#search').value.toLowerCase();const kind=document.querySelector('#kind').value;const ep=document.querySelector('#episode').value;let n=0;cards.forEach(c=>{const ok=(!q||c.textContent.toLowerCase().includes(q))&&(!kind||c.dataset.kind===kind)&&(!ep||c.dataset.episodes.split(',').includes(ep));c.hidden=!ok;if(ok)n++});document.querySelector('#count').textContent=n+' promos shown';}document.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',filter));filter();'''
    web=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuku · Visual promo playbook</title><style>{webcss}</style></head><body><main><div class="eyebrow">KUKU / VISUAL EDITORIAL PLAYBOOK</div><h1>Find the moment.<br>Cut before the answer.</h1><p class="lead">{run['episode_count']} episodes · {len(ordered)} shortlisted promos · {audit['passed']}/{audit['hard_checks']} structural checks. A visual companion generated from the actual offline run. These are script-based recommendations, not measured ad winners.</p><nav class="actions"><a href="{REPO}/raw/refs/heads/main/SOLUTION_DOC.pdf">Two-page solution PDF</a><a href="{REPO}">Run the prototype</a><a href="{REPO}/tree/main/raw_outputs">Full unedited outputs</a></nav><div class="controls"><input id="search" aria-label="Search promos" placeholder="Search hook, cliffhanger, episode, or conflict…"><select id="kind" aria-label="Edit type"><option value="">All edit types</option><option value="single">Continuous cuts</option><option value="mashup">Two-part mashups</option></select><select id="episode" aria-label="Episode"><option value="">All episodes</option>{opts}</select></div><p id="count"></p>{''.join(webcards)}<footer>Source snapshot SHA-256: {before}. Exact original cuts are preserved. This file is a presentation companion; the raw output folder remains the submission's complete unedited result. No API calls are made by this page.</footer></main><script>{js}</script></body></html>'''
    (dest/'visual_playbook.html').write_text(web)
    assert hashlib.sha256(source.read_bytes()).hexdigest()==before
    meta=dict(source_file='raw_outputs/all_episodes_promos_ranked.json',source_sha256=before,episodes=run['episode_count'],promos=len(ordered),source_checks=audit['passed'],tests_passed=tests,presentation_only=True)
    (dest/'visual_source.json').write_text(json.dumps(meta,indent=2)+'\n')
    print(f'Built visual solution HTML, three SVG assets and searchable playbook from {len(ordered)} real promos. Raw outputs unchanged.')

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--tests-passed',type=int,default=62)
    build(parser.parse_args().tests_passed)
